with with_latest as (select s.id, s.product_name, s.cost, s.stock_qty, s.launch_date, x.quantity, x.last_restock from products s left join lateral (select c.quantity, c.last_restock from inventory c where c.product_id = s.id order by c.quantity desc, c.id desc limit 1) x on true) select date_trunc('month', launch_date) as activity_month, case when cost >= 620 then 'LARGE' else 'SMALL' end as cost_tier, bit_and(stock_qty) as stock_qty_bit_and, corr(cost, stock_qty) as corr_cost_stock_qty, corr(cost, stock_qty) as corr_cost_stock_qty_2, approx_percentile(stock_qty, 0.5) as stock_qty_p50, max(cost) as max_cost, dense_rank() over (partition by date_trunc('month', launch_date) order by corr(cost, stock_qty) desc) as corr_cost_stock_qty_dense_rank from with_latest group by date_trunc('month', launch_date), case when cost >= 620 then 'LARGE' else 'SMALL' end;
